DO $muffins$
DECLARE
 j constant jsonb := $records$[{"id":"2a69d1a4-bad2-45ff-b11c-4e2f4e1b803b","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"receta-de-muffins-de-chocolate","public_path":"/receta-de-muffins-de-chocolate","source_url":"https://manualdecocina.com/receta-de-muffins-de-chocolate/","language":"es","title":"Muffins de chocolate con cacao y chispas","excerpt":"Muffins caseros de cacao y chocolate negro: mezcla suave con espátula, doce unidades propuestas y nutrición estimada por muffin.","summary":"Muffins de cacao natural y chocolate negro, hechos con aceite y dos mezclas que se unen con espátula. Se proponen 12 unidades y 72 minutos incluyendo el enfriado; fórmula, rendimiento y tiempos pendientes de prueba de cocina.","category":"Postres","category_slug":"postres","difficulty":"Fácil","course":"Postre","cuisine":"Casera","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"harina de trigo común, no leudante","amount":"200","unit":"g","group":"Secos"},{"name":"cacao natural en polvo sin azúcar","amount":"40","unit":"g","group":"Secos"},{"name":"azúcar blanco granulado","amount":"150","unit":"g","group":"Secos"},{"name":"polvo de hornear de doble acción","amount":"8","unit":"g","group":"Secos"},{"name":"sal fina","amount":"2","unit":"g","group":"Secos"},{"name":"leche entera pasteurizada","amount":"180","unit":"g","group":"Húmedos"},{"name":"huevo entero sin cáscara, pesado","amount":"100","unit":"g","group":"Húmedos"},{"name":"aceite de canola","amount":"80","unit":"g","group":"Húmedos"},{"name":"extracto de vainilla","amount":"5","unit":"g","group":"Húmedos"},{"name":"chocolate negro 60–69 %, en trocitos o chispas","amount":"100","unit":"g","group":"Chocolate"}],"steps":[{"title":"Prepara el molde y pesa los ingredientes","content":"Lávate las manos y prepara una báscula, dos cuencos, varillas, espátula, rejilla y un molde metálico estándar de 12 cavidades con cápsulas de papel. Precalienta a 180 °C con calor arriba y abajo y rejilla central; unos 15 minutos de precalentamiento se solapan con los 20 minutos de preparación. Pesa todos los ingredientes; los 100 g de huevo se pesan sin cáscara y no equivalen a un número fijo de huevos. Separa el chocolate en 80 g para la masa y 20 g para la superficie. Mantén leche y huevos refrigerados hasta usarlos.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"Muffins de chocolate: Prepara el molde y pesa los ingredientes"},{"title":"Mezcla los ingredientes secos","content":"En el primer cuenco tamiza los 200 g de harina y los 40 g de cacao. Añade los 150 g de azúcar, los 8 g de polvo de hornear y los 2 g de sal. Mezcla con varillas hasta que el color sea uniforme y no queden grumos de cacao. Usa cacao natural sin azúcar y harina común; un preparado para bebida o harina leudante requiere ajustar la fórmula.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"Muffins de chocolate: Mezcla los ingredientes secos"},{"title":"Emulsiona los ingredientes húmedos","content":"En el segundo cuenco bate a mano los 100 g de huevo, los 180 g de leche, los 80 g de aceite y los 5 g de vainilla durante aproximadamente 1 minuto, hasta que no queden vetas de clara ni grandes bolsas de aceite. No necesitas montar ni incorporar mucha espuma. Lava manos y utensilios que hayan tocado huevo crudo.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"Muffins de chocolate: Emulsiona los ingredientes húmedos"},{"title":"Une las dos mezclas sin batir en exceso","content":"Vierte los húmedos sobre los secos. Mezcla con la espátula desde el fondo, girando el cuenco, solo hasta que desaparezca la harina seca. La masa debe quedar espesa pero repartible; pequeños grumos son aceptables. Evita la batidora eléctrica y no prolongues el mezclado buscando una crema lisa. No pruebes la masa cruda: tanto el huevo como la harina deben cocinarse.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"Muffins de chocolate: Une las dos mezclas sin batir en exceso"},{"title":"Incorpora el chocolate de la masa","content":"Añade los 80 g de chocolate reservados para el interior y da unas pocas vueltas suaves con la espátula para distribuirlos. Conserva aparte los 20 g restantes. La masa sigue cruda y no debe comerse. Reparte y hornea enseguida para aprovechar el impulso del polvo de hornear.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"Muffins de chocolate: Incorpora el chocolate de la masa"},{"title":"Reparte en doce cavidades","content":"Divide la masa entre las 12 cápsulas, aproximadamente 70 g por cavidad antes del chocolate superior, sin superar tres cuartos de su altura. Reparte los 20 g de chocolate restantes por encima. El volumen del molde puede variar: si la masa no cabe, usa cápsulas adicionales en otro molde y registra el rendimiento real; las cifras nutricionales publicadas suponen exactamente 12 unidades iguales.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"Muffins de chocolate: Reparte en doce cavidades"},{"title":"Hornea y comprueba el centro","content":"Hornea en la rejilla central a 180 °C durante 22 minutos como referencia; empieza a comprobar a los 20 y prevé unos 20–25 minutos según horno y molde. Evita abrir durante los primeros 18 minutos. Pincha el centro de un muffin evitando un trozo de chocolate: el palillo puede llevar migas húmedas, pero no masa líquida. La superficie debe estar firme y el centro cocido. Si hace falta, continúa en intervalos de 2 minutos y vuelve a comprobar. Retira el molde con guantes secos.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"Muffins de chocolate: Hornea y comprueba el centro"},{"title":"Enfría en rejilla y sirve","content":"Deja los muffins 5 minutos en el molde y pásalos con cuidado a una rejilla durante unos 25 minutos más. Esos 30 minutos de enfriado se incluyen en los 72 minutos totales propuestos: 20 de preparación +22 de horno +30 de enfriado. Sirve una unidad por ración; espera a que enfríen por completo antes de taparlos. Son 12 unidades propuestas, sin ensayo de cocina ni peso final medido.","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"Muffins de chocolate: Enfría en rejilla y sirve"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"harina de trigo común","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"cacao natural sin azúcar","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"azúcar blanco","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"leche entera","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"huevo sin cáscara","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"aceite de canola","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"chocolate negro 60–69%","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"polvo de hornear de doble acción","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sal fina","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"extracto de vainilla","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"Un muffin; 12 unidades iguales propuestas, sin peso final medido","method":"Suma gramos de cada uno de los diez ingredientes por su valor USDA por 100 g y divide el total entre 12. Se incluye toda la leche, huevo, aceite, azúcar, vainilla, sal, polvo de hornear y los 100 g de chocolate, sin inventar pérdidas de nutrientes durante el horno.","note":"Estimación por ingredientes, no análisis ni prueba de cocina. Harina común modelada con harina blanca enriquecida no blanqueada; chocolate 60–69 % y polvo de hornear de doble acción son fichas de referencia y pueden variar por marca, especialmente azúcar y sodio. Si obtienes otro número de muffins, divide el total entre el rendimiento real. Los ocho nutrientes están presentes en las diez fichas; ninguna ausencia se rellena con cero."},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"Muffins de cacao y chocolate negro con copete y trocitos de chocolate, sin cobertura, sobre una rejilla"}],"published":true,"editorial_status":"published","keywords":["muffins de chocolate","muffins de cacao","muffins con chispas","muffins caseros"],"notes":"Fórmula original propuesta para 12 muffins; cantidades, volumen del molde, rendimiento y tiempos pendientes de prueba de cocina. Usa cacao natural sin azúcar, harina común y chocolate negro 60–69 %. El chocolate se reparte 80 g dentro y 20 g encima; no se añade cobertura ni decoración. Puedes cambiar canola por otro aceite neutro con textura semejante, pero la nutrición cambia; bebidas vegetales, harina integral o sin gluten y sustitutos del huevo requieren una fórmula revisada. Usa leche pasteurizada y huevos conservados en frío; no pruebes harina, huevo ni masa crudos. Lava manos, superficies y utensilios tras manipularlos. Usa guantes secos al sacar el molde y deja enfriar antes de guardar. Como propuesta doméstica prudente sin ensayo de conservación, consume en 2 días en recipiente limpio y cerrado en lugar fresco y seco; con calor o humedad, refrigera a 4 °C o menos y deja atemperar antes de servir. Para más tiempo, congela cuando estén fríos y bien envueltos hasta 1 mes como propuesta de calidad no verificada. Descarta todo el muffin si aparece moho. Contiene trigo/gluten, huevo y leche; revisa las etiquetas de chocolate y polvo de hornear. La nutrición incluye toda la receta y puede variar por marcas o sustituciones.","seo":{"title":"Muffins de chocolate: cacao y chispas paso a paso","description":"Prepara muffins de cacao y chocolate negro con ingredientes pesados y mezcla a mano. 12 unidades propuestas, tiempos completos y nutrición estimada.","image_alt":"Muffins de cacao y chocolate negro con copete y trocitos de chocolate, sin cobertura, sobre una rejilla","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"¿Qué cacao y chocolate necesito?","a":"Usa 40 g de cacao natural sin azúcar y 100 g de chocolate negro 60–69 %, repartidos en 80 g dentro y 20 g encima. Cacao de bebida azucarado o chocolate de otro porcentaje cambian la fórmula y la nutrición."},{"q":"¿Cómo evito que queden duros o crudos?","a":"Une los secos y los húmedos solo hasta que desaparezca la harina, incorpora el chocolate con pocas vueltas y hornea enseguida. A 180 °C, comprueba desde el minuto 20: el palillo puede tener migas, pero no masa líquida. Los 22 minutos son una referencia, no una prueba de cocción."},{"q":"¿Cuántos salen y cómo los guardo?","a":"Se proponen 12 muffins iguales y 72 minutos incluyendo 30 de enfriado. El tamaño del molde puede cambiar el rendimiento; ajusta la nutrición al número real. Guarda totalmente fríos en recipiente cerrado y consume en 2 días como propuesta sin ensayo; con calor o humedad, refrigera a 4 °C o menos."}]},"content_html":"<p>Muffins de cacao natural y chocolate negro, hechos con aceite y dos mezclas que se unen con espátula. Se proponen 12 unidades y 72 minutos incluyendo el enfriado; fórmula, rendimiento y tiempos pendientes de prueba de cocina.</p><p>Fórmula original propuesta para 12 muffins; cantidades, volumen del molde, rendimiento y tiempos pendientes de prueba de cocina. Usa cacao natural sin azúcar, harina común y chocolate negro 60–69 %. El chocolate se reparte 80 g dentro y 20 g encima; no se añade cobertura ni decoración. Puedes cambiar canola por otro aceite neutro con textura semejante, pero la nutrición cambia; bebidas vegetales, harina integral o sin gluten y sustitutos del huevo requieren una fórmula revisada. Usa leche pasteurizada y huevos conservados en frío; no pruebes harina, huevo ni masa crudos. Lava manos, superficies y utensilios tras manipularlos. Usa guantes secos al sacar el molde y deja enfriar antes de guardar. Como propuesta doméstica prudente sin ensayo de conservación, consume en 2 días en recipiente limpio y cerrado en lugar fresco y seco; con calor o humedad, refrigera a 4 °C o menos y deja atemperar antes de servir. Para más tiempo, congela cuando estén fríos y bien envueltos hasta 1 mes como propuesta de calidad no verificada. Descarta todo el muffin si aparece moho. Contiene trigo/gluten, huevo y leche; revisa las etiquetas de chocolate y polvo de hornear. La nutrición incluye toda la receta y puede variar por marcas o sustituciones.</p>"},{"id":"354287bc-7f8b-5a68-9a3a-68839e68ea42","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"schoko-muffin-rezept","public_path":"/de/schoko-muffin-rezept","source_url":"https://manualdecocina.com/de/schoko-muffin-rezept/","language":"de","title":"Schokomuffins mit Kakao und Schokoladenstückchen","excerpt":"Kakaomuffins mit dunkler Schokolade, vorsichtig von Hand gemischt. Vorgeschlagen sind zwölf Stück; die Nährwerte pro Muffin sind geschätzt.","summary":"Muffins mit ungesüßtem Naturkakao, dunkler Schokolade und Öl: trockene und flüssige Zutaten werden mit einem Teigschaber verbunden. Vorgeschlagen sind 12 Stück und 72 Minuten einschließlich Abkühlen; Mengen, Ausbeute und Zeiten sind noch nicht in der Küche geprüft.","category":"Desserts","category_slug":"postres","difficulty":"Einfach","course":"Dessert","cuisine":"Hausmannskost","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"Weizenmehl, ohne zugesetztes Backtriebmittel","amount":"200","unit":"g","group":"Trockene Zutaten"},{"name":"ungesüßtes, nicht alkalisiertes Kakaopulver","amount":"40","unit":"g","group":"Trockene Zutaten"},{"name":"weißer Kristallzucker","amount":"150","unit":"g","group":"Trockene Zutaten"},{"name":"doppelt wirkendes Backpulver","amount":"8","unit":"g","group":"Trockene Zutaten"},{"name":"feines Salz","amount":"2","unit":"g","group":"Trockene Zutaten"},{"name":"pasteurisierte Vollmilch","amount":"180","unit":"g","group":"Flüssige Zutaten"},{"name":"Vollei ohne Schale, abgewogen","amount":"100","unit":"g","group":"Flüssige Zutaten"},{"name":"Rapsöl","amount":"80","unit":"g","group":"Flüssige Zutaten"},{"name":"Vanilleextrakt","amount":"5","unit":"g","group":"Flüssige Zutaten"},{"name":"dunkle Schokolade mit 60–69 % Kakao, gehackt oder als Drops","amount":"100","unit":"g","group":"Schokolade"}],"steps":[{"title":"Form vorbereiten und Zutaten abwiegen","content":"Hände waschen. Waage, zwei Schüsseln, Schneebesen, Teigschaber, Kuchengitter und eine normale Metallform mit 12 Mulden und Papierförmchen bereitstellen. Ofen auf 180 °C Ober-/Unterhitze mit mittlerem Einschub vorheizen; etwa 15 Minuten Vorheizen laufen während der 20 Minuten Vorbereitung und werden nicht zusätzlich gerechnet. Alle Zutaten abwiegen; die 100 g Ei werden ohne Schale gewogen und entsprechen keiner festen Eierzahl. Schokolade in 80 g für den Teig und 20 g für die Oberfläche teilen. Milch und Eier bis zur Verwendung gekühlt halten.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Form vorbereiten und Zutaten abwiegen"},{"title":"Trockene Zutaten vermischen","content":"In die erste Schüssel 200 g Mehl und 40 g Kakao sieben. 150 g Zucker, 8 g Backpulver und 2 g Salz zugeben. Mit dem Schneebesen gleichmäßig vermischen, bis keine Kakaoklumpen mehr sichtbar sind. Naturkakao ohne Zucker und normales Mehl verwenden; gesüßtes Getränkepulver oder Mehl mit Backtriebmittel benötigen eine angepasste Rezeptur.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Trockene Zutaten vermischen"},{"title":"Flüssige Zutaten verquirlen","content":"In der zweiten Schüssel 100 g Ei, 180 g Milch, 80 g Öl und 5 g Vanille etwa 1 Minute von Hand verquirlen, bis keine Eiweißfäden oder größeren Ölansammlungen bleiben. Nicht aufschlagen; viel Schaum ist unnötig. Hände und Geräte nach Kontakt mit rohem Ei waschen.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Flüssige Zutaten verquirlen"},{"title":"Beide Mischungen kurz verbinden","content":"Flüssige Zutaten zu den trockenen gießen. Mit dem Teigschaber vom Boden her unterheben und die Schüssel drehen, nur bis kein trockenes Mehl mehr bleibt. Der Teig soll dick, aber portionierbar sein; kleine Klümpchen sind in Ordnung. Kein elektrisches Rührgerät verwenden und nicht auf eine vollkommen glatte Creme hinarbeiten. Rohen Teig nicht probieren: Ei und Mehl müssen gegart werden.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Beide Mischungen kurz verbinden"},{"title":"Schokolade unterheben","content":"Die für den Teig zurückgelegten 80 g Schokolade mit wenigen vorsichtigen Bewegungen unterheben. Die übrigen 20 g separat aufbewahren. Der Teig ist noch roh und darf nicht gegessen werden. Direkt portionieren und backen, damit das Backpulver gut wirken kann.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Schokolade unterheben"},{"title":"Auf zwölf Förmchen verteilen","content":"Teig auf die 12 Papierförmchen verteilen, ungefähr 70 g pro Mulde vor der Schokolade obenauf; höchstens drei Viertel der Höhe füllen. Die übrigen 20 g Schokolade darauf verteilen. Das Formvolumen kann variieren: Passt der Teig nicht hinein, zusätzliche Förmchen in einer weiteren Form verwenden und die tatsächliche Stückzahl notieren. Die angegebenen Nährwerte beziehen sich auf genau 12 gleich große Stücke.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Auf zwölf Förmchen verteilen"},{"title":"Backen und die Mitte prüfen","content":"Auf mittlerem Einschub bei 180 °C zunächst etwa 22 Minuten backen. Ab 20 Minuten prüfen; je nach Ofen und Form sind etwa 20–25 Minuten möglich. Den Ofen während der ersten 18 Minuten möglichst nicht öffnen. Ein Holzstäbchen in die Mitte eines Muffins stecken, ohne ein Schokoladenstück zu treffen: feuchte Krümel sind möglich, flüssiger Teig nicht. Oberfläche und Mitte müssen gegart und fest sein. Falls nötig, in Abständen von 2 Minuten weiterbacken und erneut prüfen. Form mit trockenen Ofenhandschuhen herausnehmen.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Backen und die Mitte prüfen"},{"title":"Auf dem Gitter abkühlen und servieren","content":"Muffins 5 Minuten in der Form lassen und vorsichtig auf ein Gitter setzen; etwa weitere 25 Minuten abkühlen. Diese 30 Minuten sind in den vorgeschlagenen 72 Minuten enthalten: 20 Minuten Vorbereitung +22 Minuten Backen +30 Minuten Abkühlen. Ein Stück pro Portion servieren und vor dem Verschließen vollständig abkühlen lassen. Die Ausbeute von 12 Stück ist vorgeschlagen; es gibt keinen Küchentest und kein gemessenes Endgewicht.","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"Schokomuffins mit Kakao und Schokoladenstückchen: Auf dem Gitter abkühlen und servieren"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (April 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Weizenmehl, ohne zugesetztes Backtriebmittel","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"ungesüßtes, nicht alkalisiertes Kakaopulver","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"weißer Kristallzucker","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"pasteurisierte Vollmilch","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"Vollei ohne Schale, abgewogen","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"Rapsöl","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"dunkle Schokolade mit 60–69 % Kakao, gehackt oder als Drops","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"doppelt wirkendes Backpulver","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"feines Salz","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"Vanilleextrakt","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"Ein Muffin; 12 gleich große Stücke vorgeschlagen, Endgewicht nicht gemessen","method":"Für jeden der zehn Zutatenposten die Grammmenge mit dem USDA-Wert je 100 g multiplizieren, alles summieren und durch 12 teilen. Milch, Ei, Öl, Zucker, Vanille, Salz, Backpulver und alle 100 g Schokolade sind enthalten; es werden keine Nährstoffverluste beim Backen erfunden.","note":"Zutatenbasierte Schätzung, weder Laboranalyse noch Küchentest. Normales Mehl wird durch angereichertes, ungebleichtes Allzweckmehl abgebildet; dunkle Schokolade mit 60–69 % und doppelt wirkendes Backpulver sind Referenzprodukte. Marken können vor allem Zucker und Natrium verändern. Bei anderer Ausbeute die Gesamtsumme durch die tatsächliche Stückzahl teilen. Alle acht Nährstoffe sind in allen zehn Datensätzen vorhanden; fehlende Angaben werden nicht als null eingesetzt."},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"Dunkle Kakaomuffins mit gewölbten Oberflächen und Schokoladenstückchen ohne Glasur auf einem Kuchengitter"}],"published":true,"editorial_status":"published","keywords":["Schokomuffins","Kakaomuffins","Muffins mit Schokoladenstückchen"],"notes":"Originale, noch nicht in der Küche geprüfte Rezeptur für 12 Muffins; Mengen, Formvolumen, Ausbeute und Zeiten sind Vorschläge. Naturkakao ohne Zucker, normales Mehl und dunkle Schokolade mit 60–69 % verwenden. Von der Schokolade kommen 80 g in den Teig und 20 g darauf; keine Glasur oder Dekoration hinzufügen. Rapsöl kann durch ein ähnliches neutrales Öl ersetzt werden, die Nährwerte ändern sich dabei. Pflanzendrinks, Vollkorn- oder glutenfreies Mehl und Ei-Ersatz erfordern eine überarbeitete Rezeptur. Pasteurisierte Milch und gekühlte Eier verwenden; rohes Mehl, Ei oder Teig nicht probieren. Hände, Flächen und Geräte danach reinigen. Die Form mit trockenen Ofenhandschuhen anfassen und vor dem Lagern abkühlen lassen. Als vorsichtiger, nicht auf Haltbarkeit geprüfter Haushaltsvorschlag innerhalb von 2 Tagen in einem sauberen, geschlossenen Behälter kühl und trocken verbrauchen. Bei Wärme oder Feuchtigkeit bei höchstens 4 °C kühlen und vor dem Servieren temperieren. Für längere Aufbewahrung vollständig abgekühlt gut einwickeln und bis zu 1 Monat einfrieren; auch das ist nur ein ungeprüfter Qualitätsvorschlag. Muffins mit Schimmel vollständig entsorgen. Enthält Weizen/Gluten, Ei und Milch; Schokolade und Backpulver auf dem Etikett prüfen. Alle Zutaten sind in der Nährwertschätzung enthalten; Marken und Ersatzprodukte können sie verändern.","seo":{"title":"Schokomuffins mit Kakao und Stückchen selber backen","description":"Schokomuffins mit gewogenen Zutaten und schonendem Rühren: 12 Stück als Vorschlag, vollständige Zeiten und geschätzte Nährwerte je Muffin.","image_alt":"Dunkle Kakaomuffins mit gewölbten Oberflächen und Schokoladenstückchen ohne Glasur auf einem Kuchengitter","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Welcher Kakao und welche Schokolade passen?","a":"40 g ungesüßten Naturkakao und 100 g dunkle Schokolade mit 60–69 % Kakao verwenden: 80 g im Teig und 20 g obenauf. Gesüßtes Kakaogetränkepulver oder andere Kakaogehalte verändern Rezeptur und Nährwerte."},{"q":"Wie bleiben sie locker und werden durchgebacken?","a":"Trockene und flüssige Zutaten nur kurz verbinden, Schokolade vorsichtig unterheben und sofort backen. Bei 180 °C ab Minute 20 prüfen: Krümel am Stäbchen sind möglich, flüssiger Teig nicht. 22 Minuten sind ein Richtwert, kein Beweis für den Garzustand."},{"q":"Wie viele werden es und wie lagert man sie?","a":"Vorgeschlagen sind 12 gleiche Muffins und 72 Minuten einschließlich 30 Minuten Abkühlen. Formgröße kann die Ausbeute ändern; Nährwerte auf die tatsächliche Stückzahl umrechnen. Völlig abgekühlt geschlossen lagern und als ungeprüften Vorschlag innerhalb von 2 Tagen essen; bei Wärme oder Feuchtigkeit höchstens 4 °C."}]},"content_html":"<p>Muffins mit ungesüßtem Naturkakao, dunkler Schokolade und Öl: trockene und flüssige Zutaten werden mit einem Teigschaber verbunden. Vorgeschlagen sind 12 Stück und 72 Minuten einschließlich Abkühlen; Mengen, Ausbeute und Zeiten sind noch nicht in der Küche geprüft.</p><p>Originale, noch nicht in der Küche geprüfte Rezeptur für 12 Muffins; Mengen, Formvolumen, Ausbeute und Zeiten sind Vorschläge. Naturkakao ohne Zucker, normales Mehl und dunkle Schokolade mit 60–69 % verwenden. Von der Schokolade kommen 80 g in den Teig und 20 g darauf; keine Glasur oder Dekoration hinzufügen. Rapsöl kann durch ein ähnliches neutrales Öl ersetzt werden, die Nährwerte ändern sich dabei. Pflanzendrinks, Vollkorn- oder glutenfreies Mehl und Ei-Ersatz erfordern eine überarbeitete Rezeptur. Pasteurisierte Milch und gekühlte Eier verwenden; rohes Mehl, Ei oder Teig nicht probieren. Hände, Flächen und Geräte danach reinigen. Die Form mit trockenen Ofenhandschuhen anfassen und vor dem Lagern abkühlen lassen. Als vorsichtiger, nicht auf Haltbarkeit geprüfter Haushaltsvorschlag innerhalb von 2 Tagen in einem sauberen, geschlossenen Behälter kühl und trocken verbrauchen. Bei Wärme oder Feuchtigkeit bei höchstens 4 °C kühlen und vor dem Servieren temperieren. Für längere Aufbewahrung vollständig abgekühlt gut einwickeln und bis zu 1 Monat einfrieren; auch das ist nur ein ungeprüfter Qualitätsvorschlag. Muffins mit Schimmel vollständig entsorgen. Enthält Weizen/Gluten, Ei und Milch; Schokolade und Backpulver auf dem Etikett prüfen. Alle Zutaten sind in der Nährwertschätzung enthalten; Marken und Ersatzprodukte können sie verändern.</p>"},{"id":"64e0c3ee-b943-5c5c-86b5-2d26fc2783b9","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"chocolate-muffin-recipe","public_path":"/en/chocolate-muffin-recipe","source_url":"https://manualdecocina.com/en/chocolate-muffin-recipe/","language":"en","title":"Chocolate muffins with cocoa and chocolate chips","excerpt":"Hand-mixed cocoa muffins with dark chocolate, twelve proposed servings and estimated nutrition per muffin.","summary":"Muffins made with unsweetened natural cocoa, dark chocolate and oil. Fold the separate dry and wet mixtures together with a spatula. The proposed yield is 12 muffins in 72 minutes including cooling; quantities, yield and timings await kitchen testing.","category":"Desserts","category_slug":"postres","difficulty":"Easy","course":"Dessert","cuisine":"Home cooking","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"plain all-purpose wheat flour, not self-raising","amount":"200","unit":"g","group":"Dry ingredients"},{"name":"unsweetened natural cocoa powder","amount":"40","unit":"g","group":"Dry ingredients"},{"name":"white granulated sugar","amount":"150","unit":"g","group":"Dry ingredients"},{"name":"double-acting baking powder","amount":"8","unit":"g","group":"Dry ingredients"},{"name":"fine salt","amount":"2","unit":"g","group":"Dry ingredients"},{"name":"pasteurised whole milk","amount":"180","unit":"g","group":"Wet ingredients"},{"name":"whole egg, weighed without shell","amount":"100","unit":"g","group":"Wet ingredients"},{"name":"canola oil","amount":"80","unit":"g","group":"Wet ingredients"},{"name":"vanilla extract","amount":"5","unit":"g","group":"Wet ingredients"},{"name":"dark chocolate with 60–69% cocoa, chopped or in chips","amount":"100","unit":"g","group":"Chocolate"}],"steps":[{"title":"Prepare the tin and weigh the ingredients","content":"Wash your hands. Set out scales, two bowls, a whisk, spatula, cooling rack and a standard metal 12-hole muffin tin lined with paper cases. Preheat to 180 °C conventional heat with a central rack; roughly 15 minutes of preheating overlap the 20 minutes of preparation and are not added again. Weigh every ingredient; the 100 g of egg is shell-free and does not mean a fixed number of eggs. Divide the chocolate into 80 g for the batter and 20 g for the tops. Keep milk and eggs refrigerated until needed.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Prepare the tin and weigh the ingredients"},{"title":"Mix the dry ingredients","content":"Sift 200 g flour and 40 g cocoa into the first bowl. Add 150 g sugar, 8 g baking powder and 2 g salt. Whisk until the colour is even and cocoa lumps are broken up. Use unsweetened natural cocoa and plain flour; sweetened drinking cocoa or self-raising flour requires an adjusted formula.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Mix the dry ingredients"},{"title":"Whisk the wet ingredients","content":"In the second bowl, whisk 100 g egg, 180 g milk, 80 g oil and 5 g vanilla by hand for approximately 1 minute, until there are no streaks of egg white or large pools of oil. Do not whip; plenty of foam is unnecessary. Wash hands and utensils that have touched raw egg.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Whisk the wet ingredients"},{"title":"Combine gently without overmixing","content":"Pour the wet mixture over the dry ingredients. Fold from the bottom with the spatula, turning the bowl, only until dry flour disappears. The batter should be thick but easy to portion; small lumps are fine. Avoid an electric mixer and do not keep beating to make a perfectly smooth cream. Do not taste raw batter: both egg and flour must be cooked.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Combine gently without overmixing"},{"title":"Fold in the chocolate","content":"Add the 80 g chocolate reserved for the batter and fold just a few times to distribute it. Keep the remaining 20 g separate. The batter is still raw and must not be eaten. Portion and bake promptly so the baking powder can do its work.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Fold in the chocolate"},{"title":"Fill twelve cases","content":"Divide the batter among the 12 cases, approximately 70 g per hole before the topping chocolate, filling no more than three quarters of their height. Scatter the remaining 20 g chocolate over the tops. Tin volumes vary: if the batter does not fit, use extra cases in another tin and record the actual yield. Published nutrition assumes exactly 12 equally sized muffins.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Fill twelve cases"},{"title":"Bake and check the centre","content":"Bake on the central rack at 180 °C for 22 minutes as a guide. Start checking at 20 minutes and allow around 20–25 minutes depending on oven and tin. Avoid opening the oven during the first 18 minutes. Insert a skewer into the centre of a muffin, avoiding a chocolate piece: moist crumbs are acceptable, liquid batter is not. The surface must be firm and the centre cooked. If necessary, continue in intervals of 2 minutes and check again. Remove the tin with dry oven gloves.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Bake and check the centre"},{"title":"Cool on a rack and serve","content":"Leave the muffins in the tin for 5 minutes, then carefully transfer to a rack for about 25 minutes more. These 30 minutes of cooling are included in the proposed 72-minute total: 20 minutes preparation +22 minutes baking +30 minutes cooling. Serve one muffin per portion; cool completely before covering. The yield of 12 muffins is proposed, with no kitchen test or measured finished weight.","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"Chocolate muffins with cocoa and chocolate chips: Cool on a rack and serve"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (April 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"plain all-purpose wheat flour, not self-raising","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"unsweetened natural cocoa powder","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"white granulated sugar","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"pasteurised whole milk","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"whole egg, weighed without shell","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"canola oil","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"dark chocolate with 60–69% cocoa, chopped or in chips","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"double-acting baking powder","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"fine salt","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"vanilla extract","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"One muffin; 12 equal muffins proposed, finished weight not measured","method":"Multiply each of the ten ingredient weights by its USDA value per 100 g, sum and divide by 12. Count all milk, egg, oil, sugar, vanilla, salt, baking powder and 100 g chocolate without inventing nutrient losses during baking.","note":"Ingredient-based estimate, not a laboratory analysis or kitchen test. Plain flour is represented by enriched unbleached all-purpose flour. Chocolate with 60–69% cocoa and double-acting baking powder are reference foods; brands may differ, particularly in sugar and sodium. If the yield differs, divide batch totals by the actual number. All eight nutrients are present in all ten records; missing data is never filled with zero."},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"Domed dark cocoa muffins with chocolate pieces, without icing, on a wire cooling rack"}],"published":true,"editorial_status":"published","keywords":["chocolate muffins","cocoa muffins","chocolate chip muffins"],"notes":"Original proposed formula for 12 muffins; quantities, tin volume, yield and timings await kitchen testing. Use unsweetened natural cocoa, plain flour and 60–69% dark chocolate. Divide the chocolate into 80 g inside and 20 g on top; there is no icing or decoration. Another similarly neutral oil may replace canola, but nutrition changes. Plant-based milk, wholemeal or gluten-free flour and egg replacements require a revised formula. Use pasteurised milk and refrigerated eggs; never taste raw flour, egg or batter. Wash hands, surfaces and utensils after handling them. Use dry oven gloves and cool before storing. As a cautious household suggestion without a shelf-life test, eat within 2 days, stored in a clean closed container in a cool dry place. In warm or humid conditions refrigerate at 4 °C or below and let come to room temperature before serving. For longer storage, wrap cooled muffins well and freeze for up to 1 month as an untested quality suggestion. Discard the whole muffin if mould appears. Contains wheat/gluten, egg and milk; check chocolate and baking powder labels. Estimated nutrition includes the full formula and may vary with brands or substitutions.","seo":{"title":"Chocolate muffins with cocoa and chips: step by step","description":"Make cocoa and dark chocolate muffins with weighed ingredients and gentle hand mixing. Proposed yield of 12, complete timings and estimated nutrition.","image_alt":"Domed dark cocoa muffins with chocolate pieces, without icing, on a wire cooling rack","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Which cocoa and chocolate should I use?","a":"Use 40 g unsweetened natural cocoa and 100 g dark chocolate with 60–69% cocoa: 80 g inside and 20 g on top. Sweetened drinking cocoa or chocolate with another cocoa percentage changes the formula and nutrition."},{"q":"How do I avoid tough or underbaked muffins?","a":"Combine the wet and dry ingredients only until flour disappears, fold the chocolate briefly and bake promptly. At 180 °C, check from minute 20: the skewer may carry crumbs, but no liquid batter. The proposed 22 minutes do not prove that the muffins are cooked."},{"q":"How many does this make, and how do I store them?","a":"The proposed yield is 12 equal muffins in 72 minutes including 30 minutes of cooling. Tin size can change yield; adjust nutrition to the actual number. Store completely cool in a closed container and eat within 2 days as an untested suggestion; refrigerate at 4 °C or below in warm or humid conditions."}]},"content_html":"<p>Muffins made with unsweetened natural cocoa, dark chocolate and oil. Fold the separate dry and wet mixtures together with a spatula. The proposed yield is 12 muffins in 72 minutes including cooling; quantities, yield and timings await kitchen testing.</p><p>Original proposed formula for 12 muffins; quantities, tin volume, yield and timings await kitchen testing. Use unsweetened natural cocoa, plain flour and 60–69% dark chocolate. Divide the chocolate into 80 g inside and 20 g on top; there is no icing or decoration. Another similarly neutral oil may replace canola, but nutrition changes. Plant-based milk, wholemeal or gluten-free flour and egg replacements require a revised formula. Use pasteurised milk and refrigerated eggs; never taste raw flour, egg or batter. Wash hands, surfaces and utensils after handling them. Use dry oven gloves and cool before storing. As a cautious household suggestion without a shelf-life test, eat within 2 days, stored in a clean closed container in a cool dry place. In warm or humid conditions refrigerate at 4 °C or below and let come to room temperature before serving. For longer storage, wrap cooled muffins well and freeze for up to 1 month as an untested quality suggestion. Discard the whole muffin if mould appears. Contains wheat/gluten, egg and milk; check chocolate and baking powder labels. Estimated nutrition includes the full formula and may vary with brands or substitutions.</p>"},{"id":"b25333a2-d57e-5cf1-a4f6-97608ae3f0ae","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"recette-de-muffins-au-chocolat","public_path":"/fr/recette-de-muffins-au-chocolat","source_url":"https://manualdecocina.com/fr/recette-de-muffins-au-chocolat/","language":"fr","title":"Muffins au cacao et aux pépites de chocolat","excerpt":"Des muffins au cacao naturel et au chocolat noir, mélangés délicatement à la main. Douze portions proposées et nutrition estimée par muffin.","summary":"Muffins au cacao naturel non sucré, au chocolat noir et à l’huile. Les ingrédients secs et liquides sont réunis à la spatule. Rendement proposé : 12 muffins en 72 minutes, refroidissement compris ; quantités, rendement et temps restent à vérifier en cuisine.","category":"Desserts","category_slug":"postres","difficulty":"Facile","course":"Dessert","cuisine":"Familiale","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"farine de blé ordinaire, sans levure incorporée","amount":"200","unit":"g","group":"Ingrédients secs"},{"name":"cacao naturel en poudre non sucré","amount":"40","unit":"g","group":"Ingrédients secs"},{"name":"sucre blanc en poudre","amount":"150","unit":"g","group":"Ingrédients secs"},{"name":"levure chimique à double action","amount":"8","unit":"g","group":"Ingrédients secs"},{"name":"sel fin","amount":"2","unit":"g","group":"Ingrédients secs"},{"name":"lait entier pasteurisé","amount":"180","unit":"g","group":"Ingrédients liquides"},{"name":"œuf entier pesé sans coquille","amount":"100","unit":"g","group":"Ingrédients liquides"},{"name":"huile de colza","amount":"80","unit":"g","group":"Ingrédients liquides"},{"name":"extrait de vanille","amount":"5","unit":"g","group":"Ingrédients liquides"},{"name":"chocolat noir à 60–69 %, haché ou en pépites","amount":"100","unit":"g","group":"Chocolat"}],"steps":[{"title":"Préparer le moule et peser les ingrédients","content":"Lavez-vous les mains. Préparez balance, deux saladiers, fouet, spatule, grille et moule métallique standard de 12 empreintes avec caissettes en papier. Préchauffez à 180 °C en chaleur traditionnelle, grille au milieu ; environ 15 minutes de préchauffage se déroulent pendant les 20 minutes de préparation et ne s’ajoutent pas. Pesez tout : les 100 g d’œuf sont sans coquille et ne correspondent pas à un nombre fixe d’œufs. Séparez le chocolat en 80 g pour la pâte et 20 g pour le dessus. Gardez lait et œufs au réfrigérateur jusqu’à leur utilisation.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Préparer le moule et peser les ingrédients"},{"title":"Mélanger les ingrédients secs","content":"Tamisez 200 g de farine et 40 g de cacao dans le premier saladier. Ajoutez 150 g de sucre, 8 g de levure chimique et 2 g de sel. Mélangez au fouet jusqu’à obtenir une couleur uniforme sans grumeaux de cacao. Utilisez du cacao naturel non sucré et de la farine ordinaire ; un cacao de boisson sucré ou une farine avec levure nécessite une formule adaptée.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Mélanger les ingrédients secs"},{"title":"Émulsionner les ingrédients liquides","content":"Dans le second saladier, fouettez à la main 100 g d’œuf, 180 g de lait, 80 g d’huile et 5 g de vanille pendant environ 1 minute, jusqu’à disparition des filaments de blanc et des grandes poches d’huile. Inutile de monter la préparation ou de la faire beaucoup mousser. Lavez mains et ustensiles après contact avec l’œuf cru.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Émulsionner les ingrédients liquides"},{"title":"Réunir les mélanges sans trop travailler","content":"Versez les liquides sur les ingrédients secs. Mélangez à la spatule en remontant du fond et en tournant le saladier, juste jusqu’à disparition de la farine sèche. La pâte doit rester épaisse mais facile à répartir ; de petits grumeaux sont acceptables. N’utilisez pas de batteur électrique et ne cherchez pas une crème parfaitement lisse. Ne goûtez pas la pâte crue : farine et œuf doivent cuire.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Réunir les mélanges sans trop travailler"},{"title":"Incorporer le chocolat dans la pâte","content":"Ajoutez les 80 g de chocolat réservés à l’intérieur et donnez quelques tours délicats de spatule. Conservez les 20 g restants à part. La pâte est encore crue et ne se mange pas. Répartissez et enfournez aussitôt pour profiter de l’action de la levure chimique.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Incorporer le chocolat dans la pâte"},{"title":"Répartir dans douze empreintes","content":"Partagez la pâte entre les 12 caissettes, environ 70 g par empreinte avant le chocolat supérieur, sans dépasser les trois quarts de leur hauteur. Répartissez les 20 g de chocolat restants dessus. Le volume des moules varie : si tout ne rentre pas, utilisez des caissettes supplémentaires dans un autre moule et notez le rendement réel. La nutrition indiquée suppose exactement 12 muffins égaux.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Répartir dans douze empreintes"},{"title":"Cuire et vérifier le centre","content":"Faites cuire au milieu du four à 180 °C pendant 22 minutes à titre indicatif. Vérifiez dès 20 minutes ; comptez environ 20–25 minutes selon four et moule. Évitez d’ouvrir pendant les premières 18 minutes. Piquez le centre d’un muffin sans toucher un morceau de chocolat : quelques miettes humides sont possibles, mais pas de pâte liquide. La surface doit être ferme et le centre cuit. Si nécessaire, prolongez par intervalles de 2 minutes et vérifiez à nouveau. Sortez le moule avec des gants secs.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Cuire et vérifier le centre"},{"title":"Refroidir sur grille et servir","content":"Laissez les muffins 5 minutes dans le moule, puis transférez-les délicatement sur une grille pour environ 25 minutes supplémentaires. Ces 30 minutes de refroidissement font partie des 72 minutes proposées : 20 de préparation +22 de cuisson +30 de refroidissement. Servez un muffin par portion et attendez le refroidissement complet avant de couvrir. Les 12 unités sont proposées, sans essai en cuisine ni poids final mesuré.","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"Muffins au cacao et aux pépites de chocolat: Refroidir sur grille et servir"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (April 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"farine de blé ordinaire, sans levure incorporée","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"cacao naturel en poudre non sucré","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"sucre blanc en poudre","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"lait entier pasteurisé","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"œuf entier pesé sans coquille","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"huile de colza","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"chocolat noir à 60–69 %, haché ou en pépites","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"levure chimique à double action","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sel fin","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"extrait de vanille","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"Un muffin ; 12 unités égales proposées, poids final non mesuré","method":"Multiplier le poids de chacun des dix ingrédients par sa valeur USDA pour 100 g, additionner et diviser par 12. Inclure tout le lait, œuf, huile, sucre, vanille, sel, levure et les 100 g de chocolat, sans inventer de pertes de nutriments au four.","note":"Estimation par ingrédients, sans analyse ni test en cuisine. Farine ordinaire représentée par farine blanche enrichie non blanchie ; chocolat à 60–69 % et levure à double action sont des références pouvant varier selon marque, surtout en sucre et sodium. Si le rendement change, diviser le total par le nombre réel. Les huit nutriments sont présents dans les dix fiches ; aucune absence n’est remplacée par zéro."},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"Muffins foncés au cacao, bombés et garnis de petits morceaux de chocolat, sans glaçage, sur une grille"}],"published":true,"editorial_status":"published","keywords":["muffins au chocolat","muffins au cacao","muffins aux pépites"],"notes":"Formule originale proposée pour 12 muffins ; quantités, volume du moule, rendement et temps restent à tester en cuisine. Utilisez cacao naturel non sucré, farine ordinaire et chocolat noir à 60–69 %. Répartissez le chocolat en 80 g dans la pâte et 20 g dessus ; aucun glaçage ni décor. Une autre huile neutre comparable peut remplacer le colza, mais modifie la nutrition. Boisson végétale, farine complète ou sans gluten et substitut d’œuf demandent une formule révisée. Utilisez lait pasteurisé et œufs conservés au froid ; ne goûtez jamais farine, œuf ou pâte crus. Lavez mains, surfaces et ustensiles ensuite. Utilisez des gants secs et laissez refroidir avant de ranger. À titre de proposition domestique prudente sans test de conservation, consommez sous 2 jours dans un récipient propre et fermé, au frais et au sec. Par chaleur ou humidité, réfrigérez à 4 °C maximum et laissez revenir à température avant de servir. Pour plus longtemps, emballez bien les muffins froids et congelez jusqu’à 1 mois comme proposition de qualité non vérifiée. Jetez tout le muffin en cas de moisissure. Contient blé/gluten, œuf et lait ; vérifiez les étiquettes du chocolat et de la levure. La nutrition comprend toute la formule et varie avec les marques ou substitutions.","seo":{"title":"Muffins au chocolat et cacao : les étapes détaillées","description":"Muffins au cacao et chocolat noir avec ingrédients pesés et mélange à la main. 12 unités proposées, temps complets et nutrition estimée par muffin.","image_alt":"Muffins foncés au cacao, bombés et garnis de petits morceaux de chocolat, sans glaçage, sur une grille","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Quel cacao et quel chocolat choisir ?","a":"Utilisez 40 g de cacao naturel non sucré et 100 g de chocolat noir à 60–69 % : 80 g dedans et 20 g dessus. Le cacao sucré pour boisson ou un autre pourcentage de chocolat modifie formule et nutrition."},{"q":"Comment éviter des muffins durs ou mal cuits ?","a":"Réunissez les mélanges juste jusqu’à disparition de la farine, incorporez le chocolat brièvement et enfournez aussitôt. À 180 °C, contrôlez dès la minute 20 : miettes possibles sur le pic, mais pas de pâte liquide. Les 22 minutes sont un repère et ne prouvent pas la cuisson."},{"q":"Quel rendement et quelle conservation ?","a":"On propose 12 muffins égaux et 72 minutes, dont 30 de refroidissement. Le moule peut changer le rendement ; adaptez la nutrition au nombre réel. Rangez entièrement froids, couverts, et consommez sous 2 jours comme proposition non testée ; par chaleur ou humidité, réfrigérez à 4 °C maximum."}]},"content_html":"<p>Muffins au cacao naturel non sucré, au chocolat noir et à l’huile. Les ingrédients secs et liquides sont réunis à la spatule. Rendement proposé : 12 muffins en 72 minutes, refroidissement compris ; quantités, rendement et temps restent à vérifier en cuisine.</p><p>Formule originale proposée pour 12 muffins ; quantités, volume du moule, rendement et temps restent à tester en cuisine. Utilisez cacao naturel non sucré, farine ordinaire et chocolat noir à 60–69 %. Répartissez le chocolat en 80 g dans la pâte et 20 g dessus ; aucun glaçage ni décor. Une autre huile neutre comparable peut remplacer le colza, mais modifie la nutrition. Boisson végétale, farine complète ou sans gluten et substitut d’œuf demandent une formule révisée. Utilisez lait pasteurisé et œufs conservés au froid ; ne goûtez jamais farine, œuf ou pâte crus. Lavez mains, surfaces et ustensiles ensuite. Utilisez des gants secs et laissez refroidir avant de ranger. À titre de proposition domestique prudente sans test de conservation, consommez sous 2 jours dans un récipient propre et fermé, au frais et au sec. Par chaleur ou humidité, réfrigérez à 4 °C maximum et laissez revenir à température avant de servir. Pour plus longtemps, emballez bien les muffins froids et congelez jusqu’à 1 mois comme proposition de qualité non vérifiée. Jetez tout le muffin en cas de moisissure. Contient blé/gluten, œuf et lait ; vérifiez les étiquettes du chocolat et de la levure. La nutrition comprend toute la formule et varie avec les marques ou substitutions.</p>"},{"id":"7d27cc27-02bc-5f7a-80ca-cde36422b72f","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"ricetta-muffin-al-cioccolato","public_path":"/it/ricetta-muffin-al-cioccolato","source_url":"https://manualdecocina.com/it/ricetta-muffin-al-cioccolato/","language":"it","title":"Muffin al cacao con gocce di cioccolato","excerpt":"Muffin al cacao naturale e cioccolato fondente, mescolati delicatamente a mano. Dodici porzioni proposte e valori nutrizionali stimati per muffin.","summary":"Muffin con cacao naturale non zuccherato, cioccolato fondente e olio. Ingredienti secchi e liquidi si uniscono con la spatola. Si propongono 12 muffin e 72 minuti compreso il raffreddamento; quantità, resa e tempi attendono una prova in cucina.","category":"Dolci","category_slug":"postres","difficulty":"Facile","course":"Dessert","cuisine":"Casalinga","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"farina di grano tenero comune, non autolievitante","amount":"200","unit":"g","group":"Ingredienti secchi"},{"name":"cacao naturale in polvere non zuccherato","amount":"40","unit":"g","group":"Ingredienti secchi"},{"name":"zucchero bianco semolato","amount":"150","unit":"g","group":"Ingredienti secchi"},{"name":"lievito per dolci a doppia azione","amount":"8","unit":"g","group":"Ingredienti secchi"},{"name":"sale fino","amount":"2","unit":"g","group":"Ingredienti secchi"},{"name":"latte intero pastorizzato","amount":"180","unit":"g","group":"Ingredienti liquidi"},{"name":"uovo intero pesato senza guscio","amount":"100","unit":"g","group":"Ingredienti liquidi"},{"name":"olio di colza","amount":"80","unit":"g","group":"Ingredienti liquidi"},{"name":"estratto di vaniglia","amount":"5","unit":"g","group":"Ingredienti liquidi"},{"name":"cioccolato fondente al 60–69 %, tritato o in gocce","amount":"100","unit":"g","group":"Cioccolato"}],"steps":[{"title":"Prepara lo stampo e pesa gli ingredienti","content":"Lava le mani. Prepara bilancia, due ciotole, frusta, spatola, gratella e uno stampo metallico standard da 12 muffin con pirottini di carta. Preriscalda a 180 °C in modalità statica, con ripiano centrale; circa 15 minuti di preriscaldamento si sovrappongono ai 20 minuti di preparazione e non si sommano. Pesa tutto: i 100 g di uovo sono senza guscio e non indicano un numero fisso di uova. Dividi il cioccolato in 80 g per l’impasto e 20 g per la superficie. Conserva latte e uova in frigorifero fino all’uso.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Prepara lo stampo e pesa gli ingredienti"},{"title":"Mescola gli ingredienti secchi","content":"Setaccia nella prima ciotola 200 g di farina e 40 g di cacao. Aggiungi 150 g di zucchero, 8 g di lievito e 2 g di sale. Mescola con la frusta finché il colore è uniforme e non rimangono grumi di cacao. Usa cacao naturale non zuccherato e farina comune; cacao per bevande zuccherato o farina autolievitante richiedono una formula adattata.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Mescola gli ingredienti secchi"},{"title":"Emulsiona gli ingredienti liquidi","content":"Nella seconda ciotola sbatti a mano 100 g di uovo, 180 g di latte, 80 g di olio e 5 g di vaniglia per circa 1 minuto, finché non restano filamenti di albume né grandi chiazze d’olio. Non occorre montare o creare molta schiuma. Lava mani e utensili dopo il contatto con uovo crudo.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Emulsiona gli ingredienti liquidi"},{"title":"Unisci i composti senza lavorarli troppo","content":"Versa i liquidi sugli ingredienti secchi. Mescola con la spatola dal fondo, ruotando la ciotola, solo finché la farina asciutta scompare. L’impasto deve essere denso ma porzionabile; piccoli grumi sono accettabili. Evita lo sbattitore elettrico e non continuare per ottenere una crema perfettamente liscia. Non assaggiare l’impasto crudo: sia uovo sia farina devono cuocere.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Unisci i composti senza lavorarli troppo"},{"title":"Incorpora il cioccolato nell’impasto","content":"Aggiungi gli 80 g di cioccolato riservati all’interno e distribuiscili con pochi movimenti delicati della spatola. Tieni da parte i 20 g restanti. L’impasto è ancora crudo e non deve essere mangiato. Porziona e inforna subito per sfruttare l’azione del lievito.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Incorpora il cioccolato nell’impasto"},{"title":"Distribuisci in dodici cavità","content":"Dividi l’impasto nei 12 pirottini, circa 70 g per cavità prima del cioccolato superiore, senza superare tre quarti dell’altezza. Distribuisci sopra i 20 g di cioccolato rimasti. Il volume dello stampo può variare: se l’impasto non entra, usa altri pirottini in un secondo stampo e registra la resa reale. I valori indicati presuppongono esattamente 12 muffin uguali.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Distribuisci in dodici cavità"},{"title":"Cuoci e controlla il centro","content":"Cuoci sul ripiano centrale a 180 °C per 22 minuti come riferimento. Controlla da 20 minuti e prevedi circa 20–25 minuti secondo forno e stampo. Evita di aprire nei primi 18 minuti. Inserisci uno stecchino al centro di un muffin senza toccare il cioccolato: può avere briciole umide, ma non impasto liquido. Superficie e centro devono risultare cotti e consistenti. Se necessario, prosegui a intervalli di 2 minuti e controlla di nuovo. Estrai lo stampo con guanti asciutti.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Cuoci e controlla il centro"},{"title":"Raffredda sulla gratella e servi","content":"Lascia i muffin nello stampo per 5 minuti, quindi trasferiscili con cura sulla gratella per altri 25 minuti circa. Questi 30 minuti di raffreddamento sono inclusi nei 72 minuti proposti: 20 di preparazione +22 di forno +30 di raffreddamento. Servi un muffin per porzione e aspetta che siano completamente freddi prima di coprirli. Le 12 unità sono proposte, senza prova in cucina né peso finale misurato.","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"Muffin al cacao con gocce di cioccolato: Raffredda sulla gratella e servi"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (April 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"farina di grano tenero comune, non autolievitante","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"cacao naturale in polvere non zuccherato","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"zucchero bianco semolato","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"latte intero pastorizzato","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"uovo intero pesato senza guscio","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"olio di colza","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"cioccolato fondente al 60–69 %, tritato o in gocce","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"lievito per dolci a doppia azione","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sale fino","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"estratto di vaniglia","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"Un muffin; 12 unità uguali proposte, peso finale non misurato","method":"Moltiplica i grammi di ciascuno dei dieci ingredienti per il relativo valore USDA per 100 g, somma e dividi per 12. Conta tutto il latte, uovo, olio, zucchero, vaniglia, sale, lievito e i 100 g di cioccolato, senza inventare perdite di nutrienti nel forno.","note":"Stima per ingredienti, non analisi di laboratorio o prova in cucina. Farina comune rappresentata da farina bianca arricchita non sbiancata; cioccolato al 60–69 % e lievito a doppia azione sono riferimenti. Le marche possono differire soprattutto per zucchero e sodio. Per una resa diversa, dividi i totali per il numero effettivo. Tutti gli otto nutrienti sono presenti nelle dieci schede; nessun dato mancante è sostituito da zero."},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"Muffin scuri al cacao con cupola e pezzetti di cioccolato, senza glassa, su una gratella"}],"published":true,"editorial_status":"published","keywords":["muffin al cioccolato","muffin al cacao","muffin con gocce"],"notes":"Formula originale proposta per 12 muffin; quantità, volume dello stampo, resa e tempi non sono ancora verificati in cucina. Usa cacao naturale non zuccherato, farina comune e cioccolato fondente al 60–69 %. Dividi il cioccolato in 80 g nell’impasto e 20 g sopra; niente glassa o decorazioni. Un altro olio neutro simile può sostituire quello di colza, ma cambia i valori nutrizionali. Bevande vegetali, farine integrali o senza glutine e sostituti dell’uovo richiedono una formula rivista. Usa latte pastorizzato e uova refrigerate; non assaggiare farina, uovo o impasto crudi. Lava poi mani, superfici e utensili. Usa guanti asciutti e fai raffreddare prima di conservare. Come proposta domestica prudente senza prova di conservazione, consuma entro 2 giorni in contenitore pulito e chiuso, in luogo fresco e asciutto. Con caldo o umidità, conserva a 4 °C o meno e lascia tornare a temperatura prima di servire. Per più tempo, avvolgi bene i muffin freddi e congela fino a 1 mese come proposta di qualità non verificata. In presenza di muffa scarta tutto il muffin. Contiene grano/glutine, uovo e latte; controlla le etichette di cioccolato e lievito. La stima include tutta la formula e può variare con marche o sostituzioni.","seo":{"title":"Muffin al cioccolato e cacao: tutti i passaggi","description":"Muffin al cacao e cioccolato fondente con ingredienti pesati e impasto a mano. 12 unità proposte, tempi completi e valori nutrizionali stimati.","image_alt":"Muffin scuri al cacao con cupola e pezzetti di cioccolato, senza glassa, su una gratella","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Quali cacao e cioccolato servono?","a":"Usa 40 g di cacao naturale non zuccherato e 100 g di fondente al 60–69 %: 80 g dentro e 20 g sopra. Cacao zuccherato per bevande o una diversa percentuale di cioccolato modificano formula e nutrizione."},{"q":"Come evito muffin duri o crudi al centro?","a":"Unisci i composti solo finché scompare la farina, incorpora brevemente il cioccolato e inforna subito. A 180 °C controlla dal minuto 20: sullo stecchino possono esserci briciole, non impasto liquido. I 22 minuti sono indicativi e non dimostrano la cottura."},{"q":"Quanti ne vengono e come si conservano?","a":"Si propongono 12 muffin uguali e 72 minuti, di cui 30 di raffreddamento. Lo stampo può cambiare la resa; adatta la nutrizione al numero reale. Conserva completamente freddi e coperti, consumando entro 2 giorni come proposta non testata; con caldo o umidità, refrigera a 4 °C o meno."}]},"content_html":"<p>Muffin con cacao naturale non zuccherato, cioccolato fondente e olio. Ingredienti secchi e liquidi si uniscono con la spatola. Si propongono 12 muffin e 72 minuti compreso il raffreddamento; quantità, resa e tempi attendono una prova in cucina.</p><p>Formula originale proposta per 12 muffin; quantità, volume dello stampo, resa e tempi non sono ancora verificati in cucina. Usa cacao naturale non zuccherato, farina comune e cioccolato fondente al 60–69 %. Dividi il cioccolato in 80 g nell’impasto e 20 g sopra; niente glassa o decorazioni. Un altro olio neutro simile può sostituire quello di colza, ma cambia i valori nutrizionali. Bevande vegetali, farine integrali o senza glutine e sostituti dell’uovo richiedono una formula rivista. Usa latte pastorizzato e uova refrigerate; non assaggiare farina, uovo o impasto crudi. Lava poi mani, superfici e utensili. Usa guanti asciutti e fai raffreddare prima di conservare. Come proposta domestica prudente senza prova di conservazione, consuma entro 2 giorni in contenitore pulito e chiuso, in luogo fresco e asciutto. Con caldo o umidità, conserva a 4 °C o meno e lascia tornare a temperatura prima di servire. Per più tempo, avvolgi bene i muffin freddi e congela fino a 1 mese come proposta di qualità non verificata. In presenza di muffa scarta tutto il muffin. Contiene grano/glutine, uovo e latte; controlla le etichette di cioccolato e lievito. La stima include tutta la formula e può variare con marche o sostituzioni.</p>"},{"id":"bf090861-6201-5f50-8c99-d687bed69ac4","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"チョコレートマフィン","public_path":"/ja/チョコレートマフィン","source_url":null,"language":"ja","title":"ココアとチョコチップのチョコレートマフィン","excerpt":"無糖のナチュラルココアとダークチョコレートを使い、手でやさしく混ぜるマフィン。提案量は十二個で、栄養は一個当たりの推定値です。","summary":"無糖のナチュラルココア、ダークチョコレート、油を使うマフィンです。粉類と液体を別々に混ぜ、へらで合わせます。提案量は12個、冷ます時間を含めて72分。分量、出来上がり個数、時間は調理試験による確認前の目安です。","category":"デザート","category_slug":"postres","difficulty":"簡単","course":"デザート","cuisine":"家庭料理","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"通常の小麦粉（膨張剤入りではないもの）","amount":"200","unit":"g","group":"粉類"},{"name":"無糖のナチュラルココアパウダー","amount":"40","unit":"g","group":"粉類"},{"name":"白いグラニュー糖","amount":"150","unit":"g","group":"粉類"},{"name":"二段階で作用するベーキングパウダー","amount":"8","unit":"g","group":"粉類"},{"name":"細かい塩","amount":"2","unit":"g","group":"粉類"},{"name":"殺菌済みの全乳","amount":"180","unit":"g","group":"液体材料"},{"name":"全卵（殻を除いて量る）","amount":"100","unit":"g","group":"液体材料"},{"name":"キャノーラ油","amount":"80","unit":"g","group":"液体材料"},{"name":"バニラエキストラクト","amount":"5","unit":"g","group":"液体材料"},{"name":"カカオ60–69％のダークチョコレート（刻むかチップ状）","amount":"100","unit":"g","group":"チョコレート"}],"steps":[{"title":"型を準備し、材料を量る","content":"手を洗い、はかり、ボウル二つ、泡立て器、へら、網、紙カップを敷いた標準的な金属製12個取りマフィン型を用意します。オーブンを上下加熱180 °C、中段で予熱します。約15分の予熱は20分の準備時間と重なるため、別に加算しません。すべての材料を量ります。卵100 gは殻を除いた重量で、卵の個数を固定した値ではありません。チョコレートを生地用80 gと上面用20 gに分けます。牛乳と卵は使うまで冷蔵します。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 型を準備し、材料を量る"},{"title":"粉類を混ぜる","content":"最初のボウルに小麦粉200 gとココア40 gをふるいます。砂糖150 g、ベーキングパウダー8 g、塩2 gを加え、色が均一になりココアの塊がなくなるまで泡立て器で混ぜます。無糖のナチュラルココアと通常の小麦粉を使います。加糖の飲料用ココアや膨張剤入り小麦粉では配合の調整が必要です。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 粉類を混ぜる"},{"title":"液体材料を混ぜ合わせる","content":"もう一つのボウルで卵100 g、牛乳180 g、油80 g、バニラ5 gを約1分、手で混ぜます。卵白の筋や大きな油のかたまりがなくなれば十分です。泡立ててふくらませる必要はありません。生卵に触れた手と器具を洗います。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 液体材料を混ぜ合わせる"},{"title":"混ぜすぎずに合わせる","content":"液体を粉類のボウルに注ぎます。ボウルを回しながら底からへらで返し、乾いた粉が見えなくなったところで止めます。生地は濃くても分けられる硬さにし、小さなだまは残って構いません。電動ミキサーを使わず、完全に滑らかなクリームになるまで混ぜ続けないでください。生の生地は味見しません。卵も小麦粉も加熱が必要です。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 混ぜすぎずに合わせる"},{"title":"生地用のチョコレートを加える","content":"生地用に分けたチョコレート80 gを加え、へらで数回やさしく返して散らします。残り20 gは別に取っておきます。生地はまだ生なので食べないでください。ベーキングパウダーの働きを生かすため、すぐに型へ分けて焼きます。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 生地用のチョコレートを加える"},{"title":"十二個のカップに分ける","content":"生地を12個の紙カップに均等に分けます。上面のチョコレートをのせる前で一つ約70 gとし、高さの四分の三を超えないようにします。残り20 gのチョコレートを上に分けます。型の容量は異なるので、入りきらない場合は別の型と紙カップを使い、実際の個数を記録してください。表示の栄養は同じ大きさの12個を前提としています。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 十二個のカップに分ける"},{"title":"焼いて中心を確認する","content":"中段で180 °C、22分を目安に焼きます。20分から確認し、型とオーブンにより約20–25分を見込みます。最初の18分はなるべく扉を開けません。チョコレートの塊を避けてマフィンの中心に竹串を刺します。湿った細かな焼けたくずは付いても構いませんが、液状の生地が付いてはいけません。表面がしっかりし、中心まで焼けていることを確認します。必要なら2分ずつ延長して再確認します。乾いたオーブンミトンで型を取り出します。","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 焼いて中心を確認する"},{"title":"網で冷まして盛り付ける","content":"型の中で5分置き、慎重に網へ移してさらに約25分冷まします。この30分は提案の合計72分に含まれます。準備20分＋焼成22分＋冷却30分です。一人分は一個とし、ふたをする前に完全に冷まします。提案量は12個で、調理試験は実施しておらず、出来上がり重量も未測定です。","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"ココアとチョコチップのチョコレートマフィン: 網で冷まして盛り付ける"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (April 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"通常の小麦粉（膨張剤入りではないもの）","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"無糖のナチュラルココアパウダー","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"白いグラニュー糖","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"殺菌済みの全乳","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"全卵（殻を除いて量る）","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"キャノーラ油","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"カカオ60–69％のダークチョコレート（刻むかチップ状）","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"二段階で作用するベーキングパウダー","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"細かい塩","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"バニラエキストラクト","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"一個分。同じ大きさの12個を提案し、出来上がり重量は未測定","method":"十種類の材料それぞれのグラム重量にUSDAの100 g当たりの値を掛け、合計を12で割ります。牛乳、卵、油、砂糖、バニラ、塩、ベーキングパウダー、チョコレート100 gをすべて含め、焼成中の栄養損失を推測で差し引きません。","note":"材料からの推定で、成分分析や調理試験ではありません。通常の小麦粉は栄養強化された未漂白の汎用小麦粉を参照し、カカオ60–69％のチョコレートと二段階作用のベーキングパウダーも参照食品です。特に糖分とナトリウムは銘柄で異なります。個数が変われば全体の値を実際の個数で割ってください。八項目すべてが十種類の食品データにあり、欠測をゼロで埋めていません。"},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"網の上に置いた、盛り上がったココアマフィンと小さなチョコレート片。アイシングなし"}],"published":true,"editorial_status":"published","keywords":["チョコレートマフィン","ココアマフィン","チョコチップマフィン"],"notes":"12個分の独自の提案配合です。分量、型の容量、出来上がり個数、時間は調理試験で未確認です。無糖のナチュラルココア、通常の小麦粉、カカオ60–69％のダークチョコレートを使います。チョコレート80 gを生地に、20 gを上面に使い、アイシングや飾りは加えません。キャノーラ油は似た性質のクセのない油に替えられますが、栄養は変わります。植物性飲料、全粒粉、グルテンフリー粉、卵代替品には配合の見直しが必要です。殺菌済み牛乳と冷蔵した卵を使い、生の粉、卵、生地を味見しないでください。使用後は手、台、器具を洗います。乾いたミトンを使い、保存前に冷まします。保存試験をしていない慎重な家庭向け目安として、清潔な密閉容器に入れ、涼しく乾燥した場所で2日以内に食べます。暑い、または湿度が高い場合は4 °C以下で冷蔵し、食べる前に室温に戻します。長く保存する場合は完全に冷めてから包み、品質の未確認の目安として1か月まで冷凍します。カビが出たらマフィン全体を捨ててください。小麦／グルテン、卵、乳を含みます。チョコレートとベーキングパウダーの表示も確認してください。栄養推定には全材料を含めますが、銘柄や代替により変わります。","seo":{"title":"チョコレートマフィンの作り方：ココアとチョコチップ","description":"材料を量り、へらでやさしく混ぜるココアとダークチョコレートのマフィン。提案量12個、冷却を含む時間と一個当たりの栄養推定を掲載。","image_alt":"網の上に置いた、盛り上がったココアマフィンと小さなチョコレート片。アイシングなし","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"どのココアとチョコレートを使いますか？","a":"無糖のナチュラルココア40 gとカカオ60–69％のダークチョコレート100 gを使い、80 gを生地に、20 gを上面に分けます。加糖の飲料用ココアや違うカカオ比率のチョコレートでは配合と栄養が変わります。"},{"q":"硬さや生焼けを避けるには？","a":"粉が見えなくなるまでだけ混ぜ、チョコレートを軽く加えてすぐ焼きます。180 °Cで20分から確認し、串に焼けたくずが付いても液状の生地がないことを確かめます。22分は目安で、焼けたことを保証する時間ではありません。"},{"q":"何個でき、どう保存しますか？","a":"同じ大きさの12個と、冷却30分を含む72分を提案しています。型で個数が変われば栄養も実際の個数で計算し直します。完全に冷まして密閉し、未試験の目安として2日以内に食べます。暑さや湿気がある場合は4 °C以下で冷蔵します。"}]},"content_html":"<p>無糖のナチュラルココア、ダークチョコレート、油を使うマフィンです。粉類と液体を別々に混ぜ、へらで合わせます。提案量は12個、冷ます時間を含めて72分。分量、出来上がり個数、時間は調理試験による確認前の目安です。</p><p>12個分の独自の提案配合です。分量、型の容量、出来上がり個数、時間は調理試験で未確認です。無糖のナチュラルココア、通常の小麦粉、カカオ60–69％のダークチョコレートを使います。チョコレート80 gを生地に、20 gを上面に使い、アイシングや飾りは加えません。キャノーラ油は似た性質のクセのない油に替えられますが、栄養は変わります。植物性飲料、全粒粉、グルテンフリー粉、卵代替品には配合の見直しが必要です。殺菌済み牛乳と冷蔵した卵を使い、生の粉、卵、生地を味見しないでください。使用後は手、台、器具を洗います。乾いたミトンを使い、保存前に冷まします。保存試験をしていない慎重な家庭向け目安として、清潔な密閉容器に入れ、涼しく乾燥した場所で2日以内に食べます。暑い、または湿度が高い場合は4 °C以下で冷蔵し、食べる前に室温に戻します。長く保存する場合は完全に冷めてから包み、品質の未確認の目安として1か月まで冷凍します。カビが出たらマフィン全体を捨ててください。小麦／グルテン、卵、乳を含みます。チョコレートとベーキングパウダーの表示も確認してください。栄養推定には全材料を含めますが、銘柄や代替により変わります。</p>"},{"id":"37880057-32a1-5f76-a7fa-3ac395c0a037","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"muffins-de-chocolate","public_path":"/pt/muffins-de-chocolate","source_url":null,"language":"pt","title":"Muffins de cacau com gotas de chocolate","excerpt":"Muffins de cacau natural e chocolate amargo, misturados delicadamente à mão. Doze unidades propostas e nutrição estimada por muffin.","summary":"Muffins feitos com cacau natural sem açúcar, chocolate amargo e óleo. Misture os ingredientes secos e líquidos separadamente e una com uma espátula. A proposta rende 12 unidades em 72 minutos, incluindo o resfriamento; quantidades, rendimento e tempos aguardam teste de cozinha.","category":"Sobremesas","category_slug":"postres","difficulty":"Fácil","course":"Sobremesa","cuisine":"Caseira","prep_time_minutes":20,"cook_time_minutes":22,"total_time_minutes":72,"servings":12,"ingredients":[{"name":"farinha de trigo comum, sem fermento","amount":"200","unit":"g","group":"Ingredientes secos"},{"name":"cacau natural em pó sem açúcar","amount":"40","unit":"g","group":"Ingredientes secos"},{"name":"açúcar branco granulado","amount":"150","unit":"g","group":"Ingredientes secos"},{"name":"fermento químico de dupla ação","amount":"8","unit":"g","group":"Ingredientes secos"},{"name":"sal fino","amount":"2","unit":"g","group":"Ingredientes secos"},{"name":"leite integral pasteurizado","amount":"180","unit":"g","group":"Ingredientes líquidos"},{"name":"ovo inteiro pesado sem casca","amount":"100","unit":"g","group":"Ingredientes líquidos"},{"name":"óleo de canola","amount":"80","unit":"g","group":"Ingredientes líquidos"},{"name":"extrato de baunilha","amount":"5","unit":"g","group":"Ingredientes líquidos"},{"name":"chocolate amargo com 60–69% de cacau, picado ou em gotas","amount":"100","unit":"g","group":"Chocolate"}],"steps":[{"title":"Prepare a forma e pese os ingredientes","content":"Lave as mãos. Separe balança, duas tigelas, batedor de arame, espátula, grade e uma forma metálica padrão de 12 cavidades com forminhas de papel. Preaqueça a 180 °C com calor superior e inferior e grade central; cerca de 15 minutos de preaquecimento acontecem durante os 20 minutos de preparo e não são somados novamente. Pese todos os ingredientes; os 100 g de ovo são sem casca e não equivalem a um número fixo de ovos. Divida o chocolate em 80 g para a massa e 20 g para a superfície. Mantenha leite e ovos refrigerados até o uso.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-01.webp","image_alt":"Muffins de cacau com gotas de chocolate: Prepare a forma e pese os ingredientes"},{"title":"Misture os ingredientes secos","content":"Peneire 200 g de farinha e 40 g de cacau na primeira tigela. Junte 150 g de açúcar, 8 g de fermento químico e 2 g de sal. Misture com o batedor até uniformizar a cor e desfazer os grumos de cacau. Use cacau natural sem açúcar e farinha comum; achocolatado ou farinha com fermento exigem ajuste da fórmula.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-02.webp","image_alt":"Muffins de cacau com gotas de chocolate: Misture os ingredientes secos"},{"title":"Emulsione os ingredientes líquidos","content":"Na segunda tigela, bata à mão 100 g de ovo, 180 g de leite, 80 g de óleo e 5 g de baunilha por aproximadamente 1 minuto, até desaparecerem os fios de clara e grandes poças de óleo. Não é preciso montar nem formar muita espuma. Lave mãos e utensílios que tocaram ovo cru.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-03.webp","image_alt":"Muffins de cacau com gotas de chocolate: Emulsione os ingredientes líquidos"},{"title":"Una as misturas sem bater demais","content":"Despeje os líquidos sobre os ingredientes secos. Misture com a espátula de baixo para cima, girando a tigela, apenas até sumir a farinha seca. A massa deve ficar espessa, mas fácil de dividir; pequenos grumos são aceitáveis. Evite a batedeira elétrica e não continue misturando para obter um creme perfeitamente liso. Não prove a massa crua: tanto ovo quanto farinha precisam cozinhar.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-04.webp","image_alt":"Muffins de cacau com gotas de chocolate: Una as misturas sem bater demais"},{"title":"Incorpore o chocolate da massa","content":"Adicione os 80 g de chocolate reservados para o interior e dê poucas voltas suaves com a espátula para distribuir. Mantenha os 20 g restantes separados. A massa continua crua e não deve ser consumida. Divida e leve ao forno logo em seguida para aproveitar a ação do fermento.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-05.webp","image_alt":"Muffins de cacau com gotas de chocolate: Incorpore o chocolate da massa"},{"title":"Divida em doze cavidades","content":"Distribua a massa entre as 12 forminhas, cerca de 70 g por cavidade antes do chocolate de cima, sem ultrapassar três quartos da altura. Espalhe os 20 g de chocolate restantes sobre elas. O volume da forma pode variar: se a massa não couber, use forminhas adicionais em outra forma e anote o rendimento real. A nutrição publicada pressupõe exatamente 12 unidades iguais.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-06.webp","image_alt":"Muffins de cacau com gotas de chocolate: Divida em doze cavidades"},{"title":"Asse e confira o centro","content":"Asse na grade central a 180 °C por 22 minutos como referência. Comece a conferir aos 20 minutos e considere cerca de 20–25 minutos conforme forno e forma. Evite abrir durante os primeiros 18 minutos. Espete o centro de um muffin sem atingir um pedaço de chocolate: podem aderir migalhas úmidas, mas não massa líquida. A superfície precisa estar firme e o centro cozido. Se necessário, continue em intervalos de 2 minutos e confira novamente. Retire a forma com luvas secas.","image_url":"/recetas/receta-de-muffins-de-chocolate/paso-07.webp","image_alt":"Muffins de cacau com gotas de chocolate: Asse e confira o centro"},{"title":"Esfrie na grade e sirva","content":"Deixe os muffins na forma por 5 minutos e transfira com cuidado para uma grade por cerca de mais 25 minutos. Esses 30 minutos estão incluídos nos 72 minutos totais propostos: 20 de preparo +22 de forno +30 de resfriamento. Sirva uma unidade por porção e espere esfriar completamente antes de tampar. São 12 unidades propostas, sem teste de cozinha nem peso final medido.","image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","image_alt":"Muffins de cacau com gotas de chocolate: Esfrie na grade e sirva"}],"nutrition":{"calories":246.4,"protein_g":4.4,"carbs_g":32.5,"fat_g":11.8,"saturated_fat_g":3.2,"fiber_g":2.4,"sugar_g":16.5,"sodium_mg":138,"estimated":true,"source":"USDA FoodData Central — SR Legacy (April 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"farinha de trigo comum, sem fermento","edible_grams":200,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"cacau natural em pó sem açúcar","edible_grams":40,"fdc_id":169593,"fdc_description":"Cocoa, dry powder, unsweetened","per_100g":{"calories":228,"protein_g":19.6,"carbs_g":57.9,"fat_g":13.7,"saturated_fat_g":8.07,"fiber_g":37,"sugar_g":1.75,"sodium_mg":21},"source_url":"https://fdc.nal.usda.gov/food-details/169593/nutrients"},{"ingredient":"açúcar branco granulado","edible_grams":150,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":99.8,"sodium_mg":1},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"leite integral pasteurizado","edible_grams":180,"fdc_id":171265,"fdc_description":"Milk, whole, 3.25% milkfat, with added vitamin D","per_100g":{"calories":61,"protein_g":3.15,"carbs_g":4.8,"fat_g":3.25,"saturated_fat_g":1.86,"fiber_g":0,"sugar_g":5.05,"sodium_mg":43},"source_url":"https://fdc.nal.usda.gov/food-details/171265/nutrients"},{"ingredient":"ovo inteiro pesado sem casca","edible_grams":100,"fdc_id":171287,"fdc_description":"Egg, whole, raw, fresh","per_100g":{"calories":143,"protein_g":12.6,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.13,"fiber_g":0,"sugar_g":0.37,"sodium_mg":142},"source_url":"https://fdc.nal.usda.gov/food-details/171287/nutrients"},{"ingredient":"óleo de canola","edible_grams":80,"fdc_id":172336,"fdc_description":"Oil, canola","per_100g":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.36,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source_url":"https://fdc.nal.usda.gov/food-details/172336/nutrients"},{"ingredient":"chocolate amargo com 60–69% de cacau, picado ou em gotas","edible_grams":100,"fdc_id":170272,"fdc_description":"Chocolate, dark, 60-69% cacao solids","per_100g":{"calories":579,"protein_g":6.12,"carbs_g":52.4,"fat_g":38.3,"saturated_fat_g":22,"fiber_g":8,"sugar_g":36.7,"sodium_mg":10},"source_url":"https://fdc.nal.usda.gov/food-details/170272/nutrients"},{"ingredient":"fermento químico de dupla ação","edible_grams":8,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51,"protein_g":0.1,"carbs_g":24.1,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sugar_g":0,"sodium_mg":7890},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sal fino","edible_grams":2,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":0,"sodium_mg":38800},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"},{"ingredient":"extrato de baunilha","edible_grams":5,"fdc_id":173471,"fdc_description":"Vanilla extract","per_100g":{"calories":288,"protein_g":0.06,"carbs_g":12.6,"fat_g":0.06,"saturated_fat_g":0.01,"fiber_g":0,"sugar_g":12.6,"sodium_mg":9},"source_url":"https://fdc.nal.usda.gov/food-details/173471/nutrients"}],"serving_size":"Um muffin; 12 unidades iguais propostas, peso final não medido","method":"Multiplique o peso de cada um dos dez ingredientes por seu valor USDA por 100 g, some e divida por 12. Inclua todo o leite, ovo, óleo, açúcar, baunilha, sal, fermento e os 100 g de chocolate, sem inventar perdas de nutrientes no forno.","note":"Estimativa pelos ingredientes, não análise de laboratório nem teste de cozinha. Farinha comum representada por farinha branca enriquecida não branqueada; chocolate 60–69% e fermento de dupla ação são referências. As marcas podem variar, principalmente em açúcar e sódio. Para outro rendimento, divida o total pelo número real de unidades. Os oito nutrientes constam nas dez fichas; nenhum dado ausente é preenchido com zero."},"image_url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","gallery":[{"url":"/recetas/receta-de-muffins-de-chocolate/portada.webp","alt":"Muffins escuros de cacau com topo crescido e pedaços de chocolate, sem cobertura, sobre uma grade"}],"published":true,"editorial_status":"published","keywords":["muffins de chocolate","muffins de cacau","muffins com gotas de chocolate"],"notes":"Fórmula original proposta para 12 muffins; quantidades, volume da forma, rendimento e tempos aguardam teste de cozinha. Use cacau natural sem açúcar, farinha comum e chocolate amargo 60–69%. Divida o chocolate em 80 g dentro e 20 g por cima; não há cobertura nem decoração. Outro óleo neutro semelhante pode substituir a canola, mas altera a nutrição. Bebidas vegetais, farinha integral ou sem glúten e substitutos do ovo exigem uma fórmula revisada. Use leite pasteurizado e ovos refrigerados; não prove farinha, ovo ou massa crus. Lave mãos, superfícies e utensílios depois do manuseio. Use luvas secas e deixe esfriar antes de guardar. Como proposta doméstica prudente sem teste de conservação, consuma em até 2 dias em recipiente limpo e fechado, em local fresco e seco. Com calor ou umidade, refrigere a 4 °C ou menos e deixe atingir a temperatura ambiente antes de servir. Para mais tempo, embale bem os muffins frios e congele por até 1 mês como proposta de qualidade não verificada. Descarte todo o muffin se aparecer mofo. Contém trigo/glúten, ovo e leite; confira os rótulos do chocolate e do fermento. A estimativa inclui toda a fórmula e pode variar com marcas ou substituições.","seo":{"title":"Muffins de chocolate e cacau: preparo passo a passo","description":"Faça muffins de cacau e chocolate amargo com ingredientes pesados e mistura à mão. 12 unidades propostas, tempos completos e nutrição estimada por muffin.","image_alt":"Muffins escuros de cacau com topo crescido e pedaços de chocolate, sem cobertura, sobre uma grade","image_variants":["/recetas/receta-de-muffins-de-chocolate/portada-1x1.webp","/recetas/receta-de-muffins-de-chocolate/portada-4x3.webp","/recetas/receta-de-muffins-de-chocolate/portada-16x9.webp"],"faq":[{"q":"Qual cacau e qual chocolate devo usar?","a":"Use 40 g de cacau natural sem açúcar e 100 g de chocolate amargo 60–69%: 80 g dentro e 20 g por cima. Achocolatado ou outro percentual de cacau altera a fórmula e a nutrição."},{"q":"Como evitar muffins duros ou crus?","a":"Una as misturas só até sumir a farinha, incorpore o chocolate com poucas voltas e asse logo. A 180 °C, confira a partir do minuto 20: o palito pode trazer migalhas, mas não massa líquida. Os 22 minutos são uma referência e não comprovam o ponto."},{"q":"Quantos rendem e como guardar?","a":"A proposta é de 12 muffins iguais e 72 minutos, incluindo 30 de resfriamento. O tamanho da forma pode mudar o rendimento; ajuste a nutrição ao número real. Guarde totalmente frios e tampados, consumindo em até 2 dias como proposta não testada; com calor ou umidade, refrigere a 4 °C ou menos."}]},"content_html":"<p>Muffins feitos com cacau natural sem açúcar, chocolate amargo e óleo. Misture os ingredientes secos e líquidos separadamente e una com uma espátula. A proposta rende 12 unidades em 72 minutos, incluindo o resfriamento; quantidades, rendimento e tempos aguardam teste de cozinha.</p><p>Fórmula original proposta para 12 muffins; quantidades, volume da forma, rendimento e tempos aguardam teste de cozinha. Use cacau natural sem açúcar, farinha comum e chocolate amargo 60–69%. Divida o chocolate em 80 g dentro e 20 g por cima; não há cobertura nem decoração. Outro óleo neutro semelhante pode substituir a canola, mas altera a nutrição. Bebidas vegetais, farinha integral ou sem glúten e substitutos do ovo exigem uma fórmula revisada. Use leite pasteurizado e ovos refrigerados; não prove farinha, ovo ou massa crus. Lave mãos, superfícies e utensílios depois do manuseio. Use luvas secas e deixe esfriar antes de guardar. Como proposta doméstica prudente sem teste de conservação, consuma em até 2 dias em recipiente limpo e fechado, em local fresco e seco. Com calor ou umidade, refrigere a 4 °C ou menos e deixe atingir a temperatura ambiente antes de servir. Para mais tempo, embale bem os muffins frios e congele por até 1 mês como proposta de qualidade não verificada. Descarte todo o muffin se aparecer mofo. Contém trigo/glúten, ovo e leite; confira os rótulos do chocolate e do fermento. A estimativa inclui toda a fórmula e pode variar com marcas ou substituições.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id":"2a69d1a4-bad2-45ff-b11c-4e2f4e1b803b","recipe_group_id":"7fdd9be7-e94e-4c80-9107-9fa76af45491","slug":"receta-de-muffins-de-chocolate","public_path":"/receta-de-muffins-de-chocolate","source_url":"https://manualdecocina.com/receta-de-muffins-de-chocolate/","created_at":"2026-09-23 20:50:30.190454+00","published_at":"2026-09-23 20:50:30.190454+00","expected_row_md5":"dd8c8aad7a115a41acb858642689c3f3"}$before$::jsonb;
 g constant uuid := '7fdd9be7-e94e-4c80-9107-9fa76af45491';
 outside_checksum text;
 es_count int;
 n int;
BEGIN
 IF current_setting('manualdecocina.batch04_gate',true) IS DISTINCT FROM 'ready15_deployed' THEN
  RAISE EXCEPTION 'Full15recipe lote04 publication/deployment gate not supplied';
